import javax.swing.*;import java.awt.*;import java.awt.event.*;import java.util.*;
public class AppointmentDesk extends JFrame{JTextField patient=new JTextField(18);JComboBox<String>dept=new JComboBox<>(new String[]{"Cardiology","Dental","Neurology"}),doctor=new JComboBox<>(),slot=new JComboBox<>(new String[]{"09:00","10:00","11:00","14:00"});JLabel status=new JLabel("Choose department");Map<String,String[]>docs=Map.of("Cardiology",new String[]{"Dr Kumar","Dr Priya"},"Dental",new String[]{"Dr Ravi","Dr Meena"},"Neurology",new String[]{"Dr Shah","Dr Anand"});Set<String>booked=new HashSet<>();
AppointmentDesk(){super("Outpatient Appointment Desk");setLayout(new BorderLayout());JPanel p=new JPanel(new GridLayout(4,2,5,5));p.add(new JLabel("Patient"));p.add(patient);p.add(new JLabel("Department"));p.add(dept);p.add(new JLabel("Doctor"));p.add(doctor);p.add(new JLabel("Slot"));p.add(slot);add(status,BorderLayout.NORTH);add(p);JPanel b=new JPanel();JButton book=new JButton("Book"),cancel=new JButton("Cancel");b.add(cancel);b.add(book);add(b,BorderLayout.SOUTH);dept.addItemListener(e->{if(e.getStateChange()==ItemEvent.SELECTED)refresh();});book.addActionListener(e->book());patient.addActionListener(e->book());cancel.addActionListener(e->{patient.setText("");status.setText("Cleared");});addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){if(JOptionPane.showConfirmDialog(AppointmentDesk.this,"Close?")==JOptionPane.YES_OPTION)dispose();}});refresh();setSize(500,280);setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);setLocationRelativeTo(null);}
void refresh(){doctor.removeAllItems();for(String d:docs.get((String)dept.getSelectedItem()))doctor.addItem(d);status.setText(doctor.getItemCount()+" doctors available");}void book(){String n=patient.getText().trim();if(!n.matches("[A-Za-z .]{2,40}")){status.setText("Invalid patient name");return;}String k=doctor.getSelectedItem()+"@"+slot.getSelectedItem();if(!booked.add(k)){status.setText("Slot already taken");return;}status.setText("Booked "+n+" with "+k);}public static void main(String[]a){SwingUtilities.invokeLater(()->new AppointmentDesk().setVisible(true));}}
